import {esc,btn} from './views.js';
import {hasDraft} from './workspace-flow.js';
import {completedIds,STEPS} from './guidance.js';
import {creditsOf} from './planner.js';

const quietAction=(action,label)=>`<button type="button" class="text-button home-quiet-action" data-action="${action}">${label}</button>`;
const contextLabel=context=>context==='admitted'?'Before your first semester':context==='continuing'?'Planning from your progress':'';

export function homeView(state,account=null){
 const plan=state.plan,draft=hasDraft(state),returning=!!(plan||draft),name=account?.firstName||plan?.profile?.name;
 const done=plan?completedIds(plan):[],completed=plan?creditsOf(plan.courses.filter(c=>done.includes(c.id))):0,total=plan?creditsOf(plan.courses):0;
 const step=Math.max(0,Math.min(STEPS.length-1,Number(state.journey?.step)||0)),context=contextLabel(state.journey?.studentContext?.route),review=state.phase==='draft';
 const title=returning?'Welcome back'+(name?', '+esc(name):'')+'.':account&&name?'Welcome, '+esc(name)+'.':'Plan what comes next.';
 const lead=returning?draft?'Your plan is in progress. Continue from where you left off.':'Your roadmap is ready when you are. Keep it moving with your studies.':'Explore your degree options or plan the rest of your studies at AUI.';
 const entry=`<div class="home-entry-grid" aria-label="Choose your starting point"><article class="home-entry-card home-entry-admitted" aria-labelledby="admitted-heading"><span class="eyebrow">BEFORE YOUR FIRST SEMESTER</span><h2 id="admitted-heading">Newly admitted</h2><p>Explore your interests, choose a degree direction, and build your first plan.</p><div class="home-entry-detail"><span>Start with your goals</span><span aria-hidden="true">01</span></div>${btn('entry-admitted','Build my plan',true)}</article><article class="home-entry-card home-entry-continuing" aria-labelledby="continuing-heading"><span class="eyebrow">FROM WHERE YOU ARE NOW</span><h2 id="continuing-heading">Already studying</h2><p>Start with your completed courses and current studies. Plan what remains or revisit your direction.</p><div class="home-entry-detail"><span>Start with your progress</span><span aria-hidden="true">02</span></div>${btn('entry-continuing','Plan my remaining studies',true)}</article></div><p class="home-entry-note">You can explore a degree even if you haven’t chosen one yet.</p>`;
 const progress=`<div class="home-progress"><div><span>Completed toward this plan</span><strong>${completed} <span>/ ${total} credits</span></strong></div><progress value="${completed}" max="${Math.max(1,total)}" aria-label="Credits completed toward this plan"></progress></div>`;
 const draftStatus=`<div class="home-draft-status">${context?`<span class="home-context">${esc(context)}</span>`:''}<p>${review?'Your draft is ready to review.':'Next up: '+esc(STEPS[step])}</p><span class="home-step">${review?'Review your choices before saving.':'Step '+(step+1)+' of '+STEPS.length}</span></div>`;
 const saved=`<div class="home-return-grid"><article class="welcome-card welcome-saved home-current-plan"><span class="eyebrow">${draft?'YOUR PLAN IN PROGRESS':'YOUR SAVED ROADMAP'}</span><h2>${esc(review?state.draftPlan?.program?.name||'Your next steps.':plan?.program?.name||'Your next steps.')}</h2>${draft?draftStatus:progress}<div class="card-actions">${btn('resume-plan',draft?review?'Review my draft':'Continue planning':'Open my roadmap',true)}${plan?quietAction('change-plan','Change my plan'):''}</div>${draft&&plan?quietAction('open-saved','Open my saved roadmap'):''}</article><aside class="home-next-options" aria-label="Other ways to plan"><div class="home-rethink"><span class="eyebrow">A DIFFERENT DIRECTION</span><h2>Revisit the bigger picture.</h2><p>Reconsider your goals and explore a different direction for your studies.</p>${btn('entry-rethink','Rethink my whole plan')}</div><div class="home-new-plan"><span class="home-new-label">Start fresh</span><p>Begin with new answers and a new starting point.</p>${quietAction('entry-new','Start a new plan <span aria-hidden="true">↗</span>')}</div></aside></div>`;
 return `<section class="welcome home-workspace"><div class="welcome-heading home-heading"><div><span class="eyebrow">YOUR ACADEMIC PLAN</span><h1>${title}</h1><p class="welcome-lead">${lead}</p></div>${account||returning?quietAction('my-plans','My plans <span aria-hidden="true">↗</span>'):''}</div>${returning?saved:entry}<div class="welcome-note"><span>${account?'Use My plans to return to your other roadmaps.':'Sign in to keep your plans across devices.'}</span></div></section>`;
}
